import { IEvent } from '../event-interface';
import { ListenerNode } from '../listener-node';
import { IStateData } from '../state-data';
import { IEventState } from './event-state';

export abstract class AbstractState implements IEventState {
    protected parent: IEvent;

    protected stateData: IStateData;

    constructor(parent: IEvent, stateData: IStateData) {
        this.parent = parent;
        this.stateData = stateData;
    }

    public removeListenerNode(listenerNode: ListenerNode): void {
        if (this.stateData.head === listenerNode) {
            this.stateData.head = this.stateData.head!.next;
        }
        if (this.stateData.tail === listenerNode) {
            this.stateData.tail = this.stateData.tail!.previous;
        }
        if (listenerNode.previous) {
            listenerNode.previous.next = listenerNode.next;
        }
        if (listenerNode.next) {
            listenerNode.next.previous = listenerNode.previous;
        }
    }

    public abstract addListenerNode(listenerNode: ListenerNode): void;

    public dispatchEvent(...args: any[]): void {
        let currentNode: ListenerNode | undefined = this.stateData.head;
        while (currentNode) {
            if (currentNode.once) {
                this.parent.state.removeListenerNode(currentNode);
            }
            currentNode.listener!.apply(currentNode.context, args);
            currentNode = currentNode.next;
        }
    }
}
